import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2020-08-06","description":"","frontmatter":{"title":"Ceph Performance Meeting 2020-08-06","date":"2020-08-06T00:00:00.000Z","updated":"2020-08-07T00:00:00.000Z","tags":["Ceph","性能优化","BlueStore","缓存策略","压缩测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Performance_Meeting_2020-08-06.md","filePath":"posts/2020/Ceph_Performance_Meeting_2020-08-06.md","lastUpdated":1780459816000}'),n={name:"posts/2020/Ceph_Performance_Meeting_2020-08-06.md"};function l(i,e,s,g,h,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>PR提交情况</strong>：本周收到两份PR，均来自Majiang Peng，涉及性能优化和非性能优化相关内容。</li><li><strong>性能优化</strong>：讨论了避免BlueStore中一次性刷太多数据以减少延迟峰值的PR，以及减少BlueFS缓冲列表重建的复杂PR。</li><li><strong>RGW更新</strong>：两个PR涉及rgw的d3n缓存更改，由Matt和Mark Hogan审查。</li><li><strong>未解决的PR</strong>：存在一些PR需要审查，特别是ajianpang的PR。</li><li><strong>内存优化</strong>：讨论了Igor的内存减少PR和会议主持人的双缓存优化。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li><strong>性能优化</strong>：通过改进缓存管理和数据刷新策略来优化性能，尤其是BlueStore环境中的性能。</li><li><strong>缓存策略</strong>：讨论了缓存命中和未命中对性能的影响，以及如何通过调整缓存大小和刷新策略来优化性能。</li><li><strong>压缩测试</strong>：Adam分享了压缩测试的进展，强调了均匀分布在测试中的不适用性，建议使用更接近实际工作负载的分布。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><strong>PR审查</strong>：确认了需要进一步审查的PR，包括性能优化和缓存策略相关的PR。</li><li><strong>缓存策略</strong>：讨论了双缓存策略的潜在益处和挑战，决定需要进一步的实现和测试。</li></ul><h4 id="后续的行动计划" tabindex="-1">后续的行动计划 <a class="header-anchor" href="#后续的行动计划" aria-label="Permalink to &quot;后续的行动计划&quot;">​</a></h4><ul><li><strong>PR审查</strong>：继续审查和讨论未决的PR，特别是性能和缓存相关的PR。</li><li><strong>缓存策略</strong>：进一步研究和实现双缓存策略，特别是在BlueStore环境中。</li><li><strong>压缩测试</strong>：继续进行压缩测试，特别是使用更接近实际工作负载的数据分布。</li><li><strong>性能监控</strong>：考虑在CBT测试中加入性能监控，特别是在测试开始和结束时收集性能计数器。</li></ul><h4 id="其他讨论点" tabindex="-1">其他讨论点 <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点&quot;">​</a></h4><ul><li><strong>缓存命中和未命中影响</strong>：讨论了缓存命中和未命中对性能的影响，以及如何通过调整缓存策略来优化性能。</li><li><strong>实际工作负载模拟</strong>：讨论了如何更准确地模拟实际工作负载，特别是在压缩测试中。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议讨论了多个关键议题，包括性能优化、缓存策略和压缩测试。确定了继续审查和讨论未决的PR，并进一步研究和实现双缓存策略。同时，考虑在CBT测试中加入性能监控，以更好地理解性能影响因素。</p>',13)])])}const P=a(n,[["render",l]]);export{c as __pageData,P as default};
